// src/app/components/SectionFadeIn.tsx
import { Fade } from 'react-awesome-reveal';
import { ReactNode } from 'react';

type Props = {
  children: ReactNode;
  delay?: number; // em milissegundos
};

export default function SectionFadeIn({ children, delay = 0 }: Props) {
  return (
    <Fade
      direction="up"
      triggerOnce
      delay={delay * 1000} // delay em milissegundos
      cascade={false}
      duration={700}
    >
      {children}
    </Fade>
  );
}